    'fc.help_body2' => 'Za svaki kod može se promijeniti <strong>kod</strong> (obični kodovi moraju počinjati s <code>*</code>, kodovi s promjenjivim parametrom s <code>_*</code>) i <strong>koje ga uloge smiju koristiti</strong> (prazno = svi). Samo ponašanje (što kod radi) je fiksno — ne može se dodati nova vrsta ponašanja, mogu se uređivati samo ovi kodovi.',
