    'trunks.connection_mode_help' => 'Prema IP-u: druga strana prepoznaje se po IP adresi i njezin kontakt ostaje statičan — preporučeni način za stranu s fiksnim IP-om u istoj mreži. Dolazna registracija: druga strana nam šalje SIP REGISTER i njezina se adresa uči iz te registracije. Ovaj način zahtijeva korisničko ime i lozinku; druga strana njima potvrđuje i registraciju i pozive.',
