    'sound_packs.help_title' => 'Asterisk zvučni paketi',
    'sound_packs.help_body' => 'Preuzima i instalira službene sistemske najave i glazbu na čekanju Asteriska s <code>downloads.asterisk.org</code>. Svaki paket je jedan jezik u jednom formatu; Asterisk reproducira format koji odgovara kodeku poziva, a inače ga pretvara (g722 za G.722, ulaw/alaw za operatere).<br>- <strong>Osnovno:</strong> sistemske najave, znamenke, govorna pošta. <strong>Dodatno:</strong> dodatne najave; najprije mora biti instaliran osnovni paket istog jezika.<br>- <strong>Glazba na čekanju (opsound):</strong> instalira se u <code>/var/lib/asterisk/moh/opsound</code>; za reprodukciju na kartici Glazba na čekanju izradite MOH klasu naziva <strong>opsound</strong>.<br>- <strong>Türkçe (AiPBX):</strong> vlastite turske najave AiPBX-a (GitHub izdanje, provjeren SHA256); ako su turske najave zadane, njihovim uklanjanjem sistemske najave utihnu. Uklanjanjem se brišu samo datoteke koje je paket instalirao.',
