    'system_update.help_title' => 'Kako radi ažuriranje?',
    'system_update.help_body' => 'Ažuriranje najprije sprema sigurnosnu kopiju baze podataka, postavki i Asterisk konfiguracije, zatim instalira novu verziju i provjerava radi li sve. Ako nešto ne uspije, automatski se vraća na prethodnu verziju. Tijekom ažuriranja Asterisk se ponovno pokreće: pozivi u tijeku prekidaju se, pa ažuriranje ne počinje dok su pozivi aktivni. Može se pokrenuti i na poslužitelju: <code>sudo aipbx-update</code>',
