    'certificates.help_title' => 'Vodič za certifikate',
    'certificates.help_body' => 'Portal (HTTPS), WebRTC TURNS i SIP-TLS/WSS dijele jedan certifikat; promjene ovdje primjenjuju se zajedno na Apache, coturn i Asterisk. <b>Let\'s Encrypt</b> je besplatan i sam se obnavlja; domena mora pokazivati na ovaj poslužitelj, a port 80 mora biti dostupan s interneta. Ako vaša organizacija ima certifikat, <b>učitajte ga</b> (PEM ili PFX); učitani certifikati ne obnavljaju se automatski, učitajte novi prije isteka. Sa <b>samopotpisanim</b> certifikatom preglednici prikazuju upozorenje, a TURNS u preglednicima ne radi: WebRTC pozivi iza vatrozida mogu biti bez zvuka.',
