    'queue_reports.help_body' => 'Svaki poziv koji uđe u red broji se jednom. <b>Odgovoreni</b>: spojeni s agentom. <b>Izgubljeni</b>: pozivatelj je prekinuo dok je čekao ili je isteklo vrijeme reda. <b>Kratko napuštanje</b>: prekinuto unutar %d sekundi; ne ulazi u razinu usluge. <b>Razina usluge</b>: pozivi odgovoreni unutar cilja u odnosu na sve pozive osim kratkih napuštanja. <b>ASA</b>: prosječno čekanje odgovorenih poziva. <b>AHT</b>: prosječno vrijeme razgovora. <b>Stopa javljanja</b> (agent): koliko se često agent javio kad mu je red zvonio. <b>Povratni poziv</b>: izgubljeni poziv smatra se riješenim kad je taj broj kasnije nazvan s lokala ili je ponovno nazvao i dobio odgovor. Podaci dolaze iz Asteriskova zapisa redova; izvješće se može preuzeti kao PDF ili Excel.',
