    'ai_tts.help_body' => 'Pretvara tekst u prirodan govor pomoću usluga u oblaku (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Poslušajte rezultat, preuzmite ga kao MP3 ili ga jednim klikom spremite kao <b>najavu</b>: pretvara se u Asteriskov format (8 kHz WAV) i dodaje u Zvukove i najave za IVR-ove, dolazne rute i vremenske uvjete (vrijedi nakon Primijeni). <b>Ove su usluge plaćene</b> i naplaćuju se po znaku; svaka sinteza čuva se u povijesti s brojem znakova. Pristupni ključevi dolaze iz konzole svakog pružatelja, spremaju se šifrirano i nikad se više ne prikazuju na stranici.',
