    'mailtpl.invite_new.body' => '<p>Poštovani {name},</p>{mobile_section}<p>Vaš račun na centrali <strong>{brand}</strong> je spreman. Za prijavu postavite lozinku pomoću gumba u nastavku.</p>{account_details}{reset_button}<p>Ako gumb ne radi, otvorite ovu poveznicu: {reset_link}</p><p><em>Poveznica za lozinku vrijedi 48 sati i radi jednom. Ako niste očekivali ovaj e-mail, obratite se administratoru sustava.</em></p>',
