    'storage.help_title' => 'Gdje se čuvaju chat datoteke',
    'storage.help_body' => '<p>Privici u chatu, njihove sličice i slike grupa prema zadanim postavkama spremaju se na disk poslužitelja (<code>/var/lib/aipbx/chat_files</code>). Uz pohranu kompatibilnu sa S3 (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) one umjesto toga idu u bucket, a velike datoteke ne opterećuju PBX.</p><p>Preuzimanja i dalje idu preko chat usluge, pa datoteke chata mogu otvoriti samo njegovi sudionici; bucket može ostati privatan. Datoteke spremljene prije promjene i dalje se poslužuju s diska dok ih ne premjestite. Postavke bucketa provjeravaju se prije spremanja.</p><p>Snimke poziva, govorna pošta i faksovi ostaju na lokalnom disku.</p>',
