    'netsvc.help_title' => 'Mrežne usluge',
    'netsvc.help_body' => 'Stolni telefoni sami pronalaze poslužitelj za provisioning kad DHCP poslužitelj dijeli njegovu adresu (opcija 66). DHCP i TFTP uključuju se zasebno. Kad je <strong>DHCP poslužitelj</strong> isključen, ostaje vaš vlastiti DHCP poslužitelj: ondje postavite dolje navedene opcije. Kad je uključen, AiPBX dijeli adrese na jednom sučelju ili VLAN-u. <strong>TFTP poslužitelj</strong> poslužuje boot datoteke i firmver koje učitate. Konfiguracija pojedinog telefona (sa SIP lozinkom) uvijek se poslužuje preko HTTPS-a, nikad preko TFTP-a.',
