    'web_widgets.help_body' => 'Widget postavlja gumb "Nazovite nas" na bilo koju web-stranicu. Posjetitelji razgovaraju s vama iz preglednika putem WebRTC-a ili ostave svoj broj, a PBX ih nazove. Zalijepite jednoretčani kod u web-stranicu (ili u WordPress dodatak) i nakon spremanja pritisnite <strong>Primijeni</strong>.',
    'web_widgets.help_number' => 'Broj:',
