    'web_widgets.help_security' => 'Sigurnost:',
    'web_widgets.help_security_desc' => 'Widget mogu koristiti samo dopuštene web-stranice. Svaki poziv treba jednokratni token, a ograničenja (po IP-u, po danu, istodobni pozivi, trajanje poziva) vrijede za svaki zahtjev. Svaki se zahtjev bilježi u nastavku.',
